package com.hrms.employee.entity;

import com.hrms.common.audit.Auditable;
import com.hrms.common.enums.Gender;
import com.hrms.common.util.BooleanToNumberConverter;
import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDate;

/**
 * Dependant of an employee (table EMPLOYEE_DEPENDENTS, created by V5). Never deleted, only deactivated.
 * Generated by tools/generate_employee_info.py.
 */
@Entity
@Table(name = "EMPLOYEE_DEPENDENTS", schema = "HRMS")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class EmployeeDependent extends Auditable {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "employee_dependents_seq")
    @SequenceGenerator(name = "employee_dependents_seq", sequenceName = "HRMS.SEQ_EMPLOYEE_DEPENDENTS", allocationSize = 1)
    @Column(name = "DEPENDENT_ID", nullable = false)
    private Long id;

    @Column(name = "EMPLOYEE_ID", nullable = false)
    private Long employeeId;

    @Column(name = "RELATION_ID", nullable = false)
    private Long relationId;

    @Column(name = "FIRST_NAME", nullable = false, length = 100)
    private String firstName;

    @Column(name = "MIDDLE_NAME", length = 100)
    private String middleName;

    @Column(name = "LAST_NAME", length = 100)
    private String lastName;

    @Column(name = "FIRST_NAME_AR", columnDefinition = "NVARCHAR2(200)")
    private String firstNameAr;

    @Column(name = "MIDDLE_NAME_AR", columnDefinition = "NVARCHAR2(200)")
    private String middleNameAr;

    @Column(name = "LAST_NAME_AR", columnDefinition = "NVARCHAR2(200)")
    private String lastNameAr;

    @Enumerated(EnumType.STRING)
    @Column(name = "GENDER", length = 20)
    private Gender gender;

    @Column(name = "DATE_OF_BIRTH")
    private LocalDate dateOfBirth;

    @Column(name = "BIRTH_PLACE", length = 80)
    private String birthPlace;

    @Convert(converter = BooleanToNumberConverter.class)
    @Column(name = "IS_ALIVE", nullable = false)
    private Boolean isAlive;

    @Column(name = "PHONE", length = 30)
    private String phone;

    @Column(name = "ADDRESS", length = 200)
    private String address;

    @Convert(converter = BooleanToNumberConverter.class)
    @Column(name = "IS_ACTIVE", nullable = false)
    private Boolean isActive;

    /** Optimistic lock: a stale writer gets HTTP 409. */
    @Version
    @Column(name = "VERSION", nullable = false)
    private Long version;
}
